-- 20-playoff-bracket. Reviewed uploaded workbook only; save pending edits and back up first.
-- Run ENTIRE file in DB Browser, verify counts, then Write Changes.
-- SAVEPOINT supports an existing transaction. No records are replaced.
-- Six frozen seeds; two first-seed byes; ten resolved game-side slots.
PRAGMA foreign_keys=ON;
SAVEPOINT afl_remaining_20;
CREATE TEMP TABLE afl_remaining_20_0 AS SELECT id, season_id, division_id, seed, team_id, seeded_at, source_import_batch_id FROM playoff_seedings WHERE 0;
CREATE TEMP TABLE afl_remaining_20_1 AS SELECT id, season_id, division_id, round, game_id, side, source_type, source_seed_id, source_game_id, resolved_team_id, resolved_at FROM bracket_slots WHERE 0;
CREATE TEMP TABLE afl_remaining_20_guard(ok INTEGER);
CREATE TEMP TRIGGER afl_remaining_20_check BEFORE INSERT ON afl_remaining_20_guard
BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM leagues WHERE id='36c6e53f-7be2-5a94-84a8-0df871aae9fd' AND name='AFL') THEN RAISE(ROLLBACK,'Missing AFL league.') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM seasons WHERE id='97808f43-a0d5-5251-bf8d-fae1643c8258' AND league_id='36c6e53f-7be2-5a94-84a8-0df871aae9fd') THEN RAISE(ROLLBACK,'Import 05 season first.') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM schema_migrations WHERE version=2) THEN RAISE(ROLLBACK,'Apply schema upgrade 10 first.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_20_0 i JOIN playoff_seedings t ON t.id=i.id WHERE t.season_id IS NOT i.season_id OR t.division_id IS NOT i.division_id OR t.seed IS NOT i.seed OR t.team_id IS NOT i.team_id OR t.seeded_at IS NOT i.seeded_at OR t.source_import_batch_id IS NOT i.source_import_batch_id) THEN RAISE(ROLLBACK,'playoff_seedings: existing record differs; no overwrite.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_20_0 i JOIN playoff_seedings t ON t.season_id=i.season_id AND (t.team_id=i.team_id OR (t.division_id=i.division_id AND t.seed=i.seed)) WHERE NOT (t.id=i.id)) THEN RAISE(ROLLBACK,'playoff_seedings: natural key uses another ID.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_20_1 i JOIN bracket_slots t ON t.id=i.id WHERE t.season_id IS NOT i.season_id OR t.division_id IS NOT i.division_id OR t.round IS NOT i.round OR t.game_id IS NOT i.game_id OR t.side IS NOT i.side OR t.source_type IS NOT i.source_type OR t.source_seed_id IS NOT i.source_seed_id OR t.source_game_id IS NOT i.source_game_id OR t.resolved_team_id IS NOT i.resolved_team_id OR t.resolved_at IS NOT i.resolved_at) THEN RAISE(ROLLBACK,'bracket_slots: existing record differs; no overwrite.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_20_1 i JOIN bracket_slots t ON t.game_id=i.game_id AND t.side=i.side WHERE NOT (t.id=i.id)) THEN RAISE(ROLLBACK,'bracket_slots: natural key uses another ID.') END;
END;
DROP TRIGGER afl_remaining_20_check;
DROP TABLE afl_remaining_20_guard;
DROP TABLE afl_remaining_20_0;
DROP TABLE afl_remaining_20_1;
RELEASE SAVEPOINT afl_remaining_20;
PRAGMA foreign_key_check;
SELECT 'playoff_seedings' AS imported_table,count(*) AS reviewed_records_present FROM playoff_seedings t WHERE EXISTS(SELECT 1 FROM source_record_mappings m WHERE m.import_batch_id='3e64ef48-6df3-5c48-afb3-47e656096919' AND m.target_table='playoff_seedings' AND m.target_id=CAST(t.id AS TEXT))
UNION ALL
SELECT 'bracket_slots' AS imported_table,count(*) AS reviewed_records_present FROM bracket_slots t WHERE EXISTS(SELECT 1 FROM source_record_mappings m WHERE m.import_batch_id='3e64ef48-6df3-5c48-afb3-47e656096919' AND m.target_table='bracket_slots' AND m.target_id=CAST(t.id AS TEXT));
